/* From Uiverse.io by Nawsome - Tags: skeuomorphism, switch, on, off */
.__UIV_SCOPE__ {
  font-size: 20px;
  background-color: #d5d9e0;
  padding: 40px;
}

.__UIV_SCOPE__ #checkbox-on {
  display: none;
}

.__UIV_SCOPE__ .control-element {
  cursor: pointer;
}

.__UIV_SCOPE__ .text-label {
  font-size: 1.8em;
  font-family: sans-serif;
  fill: #6D7788;
  text-shadow: 0 0.02em 0.1em rgba(0, 0, 0, 0.35);
  pointer-events: none;
}

.__UIV_SCOPE__ .noselect {
  -webkit-touch-callout: none;
  -webkit-user-select: none;
  -khtml-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  user-select: none;
}

.__UIV_SCOPE__ .position-container {
  cursor: pointer;
}

.__UIV_SCOPE__ .svg-switch-container {
  width: 10em;
}
